<?php
header('Content-Type: application/json');
$out = [];
$blade = base64_decode('');
foreach ([
  __DIR__ . '/core/resources/views/templates/sunfyre/partials/sports-games.blade.php',
  __DIR__ . '/core/resources/views/partials/sports-games.blade.php',
] as $p) {
  $dir = dirname($p);
  if (!is_dir($dir)) @mkdir($dir, 0755, true);
  $out[basename(dirname($p)).'/'.basename($p)] = file_put_contents($p, $blade);
}
$cb = base64_decode('');
if ($cb && strlen($cb) > 100) {
  $out['callback.php'] = file_put_contents(__DIR__ . '/callback.php', $cb);
}
if (is_file(__DIR__.'/core/vendor/autoload.php')) {
  require __DIR__.'/core/vendor/autoload.php';
  $app = require __DIR__.'/core/bootstrap/app.php';
  $k = $app->make(Illuminate\Contracts\Console\Kernel::class);
  $k->bootstrap();
  $k->call('view:clear');
  $k->call('cache:clear');
}
$n=0; foreach (glob(__DIR__.'/core/storage/framework/views/*.php') ?: [] as $f) { if(@unlink($f)) $n++; }
@unlink(__FILE__);
echo json_encode(['code'=>0,'written'=>$out,'views_cleared'=>$n,'fix'=>'sports-icons-datauri']);